from bank import STRAND


def H(text):
    """w|py|clue|en|example|src|wenyan|tip|hint"""
    out = []
    for line in text.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        p = [x.strip() for x in line.split("|")]
        assert len(p) == 9, line
        w, py, clue, en, ex, src, wy, tip, hint = p
        out.append(dict(w=w, py=py, clue=clue, en=en, ex=ex, strand=STRAND["L"], tip=tip, src=src, hint=hint,
                        wenyan=wy, panels=[], panelNote=""))
    return out


